from copy import deepcopy
from itertools import permutations
from scheduler import execution_order

cases = [({}, []), ({'solo': []}, ['solo']), ({'z': [], 'b': [], 'a': ['b']}, ['b', 'a', 'z']), ({'build': ['fetch', 'fetch'], 'fetch': []}, ['fetch', 'build']), ({'a': ['c'], 'b': [], 'c': []}, ['b', 'c', 'a'])]
for jobs, expected in cases:
    before = deepcopy(jobs)
    assert execution_order(jobs) == expected
    assert jobs == before
for jobs in [{'a': ['missing']}, {'a': ['a']}, {'a': ['b'], 'b': ['a']}, {'free': [], 'a': ['b'], 'b': ['a']}]:
    before = deepcopy(jobs)
    try:
        execution_order(jobs)
    except ValueError:
        pass
    else:
        raise AssertionError(f'Expected ValueError for {jobs}')
    assert jobs == before

names = ('a', 'b', 'c')
edges = [(task, prerequisite) for task in names for prerequisite in names]
orders = list(permutations(names))
for mask in range(1 << len(edges)):
    jobs = {name: [] for name in reversed(names)}
    for bit, (task, prerequisite) in enumerate(edges):
        if mask & (1 << bit):
            jobs[task].extend([prerequisite, prerequisite])
    valid = [order for order in orders if all(order.index(prerequisite) < order.index(task) for task in names for prerequisite in jobs[task])]
    before = deepcopy(jobs)
    try:
        actual = execution_order(jobs)
    except ValueError:
        assert not valid, jobs
    else:
        assert valid and actual == list(min(valid)), (jobs, actual, valid)
    assert jobs == before
print('Edge cases and all 512 directed graphs on three tasks passed.')
